import sys, os, base64

BRAND = ''
ICONS = {'android_icons/mipmap-hdpi/ic_launcher.png': '', 'android_icons/mipmap-mdpi/ic_launcher.png': '', 'android_icons/mipmap-xhdpi/ic_launcher.png': '', 'android_icons/mipmap-xxhdpi/ic_launcher.png': '', 'android_icons/mipmap-xxxhdpi/ic_launcher.png': ''}

def rd(p):
    return open(p, encoding='utf-8').read()

def rep(s, old, new, name):
    if s.count(old) != 1:
        print('NOT FOUND/AMBIGUOUS:', name)
        sys.exit(1)
    return s.replace(old, new, 1)

if os.path.exists('lib/brand.dart'):
    print('already patched'); sys.exit(0)
if not os.path.exists('lib/netinfo.dart'):
    print('شغّل patch5 و patch6 أولًا'); sys.exit(1)

m = rd('lib/main.dart')
m = rep(m, "import 'modes.dart';\n", "import 'modes.dart';\nimport 'brand.dart';\n", 'main import')
m = rep(m, "  Map<String, String> sig = {}, nm = {}, tr = {};\n",
        "  Map<String, String> sig = {}, nm = {}, tr = {}, stx = {};\n", 'stx field')
m = rep(m, "    if (!mounted) return;\n    setState(() {\n      sig = Huawei.kv(s);\n",
        """    Map<String, String> sx = stx;
    try {
      sx = Huawei.kv(await hw!.get('monitoring/status'));
    } catch (_) {}
    if (!mounted) return;
    setState(() {
      stx = sx;
      sig = Huawei.kv(s);
""", 'refresh status')
m = rep(m, "            Icon(kIcons[cur?.icon] ?? Icons.router, color: kGreen),\n",
        "            (cur?.icon == null || cur?.icon == 'router')\n                ? const KifiBadge(size: 30)\n                : Icon(kIcons[cur?.icon] ?? Icons.router, color: kGreen),\n", 'header icon')
m = rep(m, "...(tab == 0 ? cellTab() : tab == 1 ? routerTab() : chartsTab()),",
        "...(tab == 0 ? <Widget>[SignalHero(sig: sig, st: stx), ...cellTab()] : tab == 1 ? routerTab() : chartsTab()),", 'hero')

b = rd('.github/workflows/build.yml')
b = rep(b, """          if [ -n "$K" ]; then cp -f android_src/MainActivity.kt "$K"; fi
""", """          if [ -n "$K" ]; then cp -f android_src/MainActivity.kt "$K"; fi
          R=app/android/app/src/main/res
          rm -f $R/mipmap-anydpi-v26/ic_launcher*.xml
          cp -r android_icons/. $R/
""", 'yml icons')

open('lib/main.dart', 'w', encoding='utf-8').write(m)
open('.github/workflows/build.yml', 'w', encoding='utf-8').write(b)
open('lib/brand.dart', 'wb').write(base64.b64decode(BRAND))
for p, v in ICONS.items():
    os.makedirs(os.path.dirname(p), exist_ok=True)
    open(p, 'wb').write(base64.b64decode(v))
print('patched OK')
